import{_ as t,c as e,o as i,ae as r}from"./chunks/framework.CliRSA9F.js";const s="/images/show_visibility.webp",g=JSON.parse('{"title":"Show Visibility","description":"","frontmatter":{},"headers":[],"relativePath":"features/show-visibility.md","filePath":"features/show-visibility.md"}'),a={name:"features/show-visibility.md"};function n(l,o,p,h,c,d){return i(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="show-visibility" tabindex="-1">Show Visibility <a class="header-anchor" href="#show-visibility" aria-label="Permalink to &quot;Show Visibility&quot;">​</a></h1><h2 id="track-your-podcast-s-organic-search-performance" tabindex="-1">Track Your Podcast&#39;s Organic Search Performance <a class="header-anchor" href="#track-your-podcast-s-organic-search-performance" aria-label="Permalink to &quot;Track Your Podcast&#39;s Organic Search Performance&quot;">​</a></h2><p>Show Visibility reveals where your podcast appears when people search for keywords on major platforms (Apple Podcasts, Spotify, Amazon Music, YouTube Music). Each number shows your podcast&#39;s ranking position for that keyword - lower numbers indicate better rankings.</p><p>In the app, this is the <strong>show view of the Organic Visibility tab</strong> (the tab is labeled &quot;Organic Visibility&quot; in the Search Visibility navigation). The same tab also has an episode view—see <a href="/features/episode-visibility.html">Episode Visibility</a>—but this article covers the show-level view.</p><p><strong>Why This Matters</strong>: Show Visibility works as an opportunistic discovery tool, showing where your podcast is ALREADY ranking across platforms. The biggest traffic boost comes from reaching the top 3-5 results, so use this feature to identify keywords where you&#39;re close (#6-10) and can realistically push into high-visibility positions with targeted optimization.</p><p><img src="'+s+'" alt="Show Visibility Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>Free Plan Note</strong>: Free users can see the first 10 rows only. Additional keyword rankings are blurred with a lock symbol and require an upgrade for full access.</p><h2 id="the-strategic-value-of-keyword-ranking-data" tabindex="-1"><strong>The Strategic Value of Keyword Ranking Data</strong> <a class="header-anchor" href="#the-strategic-value-of-keyword-ranking-data" aria-label="Permalink to &quot;**The Strategic Value of Keyword Ranking Data**&quot;">​</a></h2><h3 id="turn-visibility-into-discovery" tabindex="-1"><strong>Turn Visibility Into Discovery</strong> <a class="header-anchor" href="#turn-visibility-into-discovery" aria-label="Permalink to &quot;**Turn Visibility Into Discovery**&quot;">​</a></h3><p>Rankings aren&#39;t just numbers - they represent real discovery opportunities. Since most listeners choose from the top 3-5 results, improving from #8 to #4 can dramatically increase how many people find your show. The key is identifying where you&#39;re already close to these high-visibility positions and optimizing strategically.</p><h3 id="the-opportunistic-approach-to-keyword-optimization" tabindex="-1"><strong>The Opportunistic Approach to Keyword Optimization</strong> <a class="header-anchor" href="#the-opportunistic-approach-to-keyword-optimization" aria-label="Permalink to &quot;**The Opportunistic Approach to Keyword Optimization**&quot;">​</a></h3><p>Show Visibility reveals where you&#39;re ALREADY appearing in search results. Use this data opportunistically:</p><ul><li><strong>High-Impact Targets</strong>: Keywords where you rank #6-10 - closest to the high-visibility top 5 positions</li><li><strong>Current Strengths</strong>: Keywords where you already rank top 5 - maintain and reinforce these wins</li><li><strong>Platform-Specific Gaps</strong>: Keywords ranking well on one platform but not others - cross-platform optimization opportunities</li></ul><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ol><li><p><strong>Keyword Rankings Table</strong>: Displays keywords your podcast ranks for, showing the keyword text, search volume, and your ranking position on each platform. Only keywords where your podcast ranks within the <strong>top 50</strong> appear here.</p></li><li><p><strong>Platform Rankings</strong>: Shows ranking position for each keyword on Apple Podcasts, Spotify, Amazon Music, and YouTube Music</p></li><li><p><strong>Search Volume</strong>: Progress bars showing estimated monthly search volume</p></li><li><p><strong>Track Keywords</strong>: Click the &quot;Track&quot; button to add keywords to your Keyword Strategy for monitoring</p></li><li><p><strong>Sortable Columns</strong>: Click platform headers to sort by ranking position - lower numbers mean better visibility</p></li></ol><h2 id="how-to-use-show-visibility-strategically" tabindex="-1"><strong>How to Use Show Visibility Strategically</strong> <a class="header-anchor" href="#how-to-use-show-visibility-strategically" aria-label="Permalink to &quot;**How to Use Show Visibility Strategically**&quot;">​</a></h2><h3 id="step-1-find-your-opportunistic-wins" tabindex="-1"><strong>Step 1: Find Your Opportunistic Wins</strong> <a class="header-anchor" href="#step-1-find-your-opportunistic-wins" aria-label="Permalink to &quot;**Step 1: Find Your Opportunistic Wins**&quot;">​</a></h3><p><strong>Focus on Where You&#39;re Already Close</strong>: The biggest traffic boost comes from reaching the top 3-5 results on each platform. Look for keywords where you already rank in positions #6-15 with decent search volume - these represent realistic opportunities to push into the high-visibility zone with focused optimization.</p><h3 id="step-2-understand-platform-specific-performance" tabindex="-1"><strong>Step 2: Understand Platform-Specific Performance</strong> <a class="header-anchor" href="#step-2-understand-platform-specific-performance" aria-label="Permalink to &quot;**Step 2: Understand Platform-Specific Performance**&quot;">​</a></h3><p><strong>Sort by Platform</strong>: Click platform column headers (Apple Podcasts, Spotify, etc.) to identify where your optimization efforts should focus. You might rank well on Apple but poorly on Spotify for the same keyword.</p><h3 id="step-3-use-it-as-an-opportunistic-discovery-tool" tabindex="-1"><strong>Step 3: Use It as an Opportunistic Discovery Tool</strong> <a class="header-anchor" href="#step-3-use-it-as-an-opportunistic-discovery-tool" aria-label="Permalink to &quot;**Step 3: Use It as an Opportunistic Discovery Tool**&quot;">​</a></h3><p><strong>Analyze Where You&#39;re Already Ranking</strong>: Show Visibility shows where your podcast is currently appearing in search results. Use this data to identify:</p><ul><li><strong>High-Priority Opportunities</strong>: Keywords where you rank #6-10 and could reach top 5 with optimization</li><li><strong>Existing Strengths</strong>: Keywords where you already rank top 5 - maintain and reinforce these positions</li><li><strong>Platform Gaps</strong>: Keywords performing well on one platform (#3-5) but poorly on others - cross-platform optimization opportunities</li></ul><h3 id="step-4-build-your-tracking-strategy" tabindex="-1"><strong>Step 4: Build Your Tracking Strategy</strong> <a class="header-anchor" href="#step-4-build-your-tracking-strategy" aria-label="Permalink to &quot;**Step 4: Build Your Tracking Strategy**&quot;">​</a></h3><p><strong>Track Opportunities Systematically</strong>: Click the &quot;Track&quot; button on keywords that meet your strategic criteria. Don&#39;t track everything - focus on keywords that align with your content and audience goals.</p><h3 id="step-5-monitor-your-progress-toward-top-rankings" tabindex="-1"><strong>Step 5: Monitor Your Progress Toward Top Rankings</strong> <a class="header-anchor" href="#step-5-monitor-your-progress-toward-top-rankings" aria-label="Permalink to &quot;**Step 5: Monitor Your Progress Toward Top Rankings**&quot;">​</a></h3><p><strong>Track Movement Into Top Positions</strong>: Focus on monitoring keywords where you&#39;re moving closer to the top 3-5 positions. Small improvements from #8 to #4 can dramatically increase your visibility and listener discovery more than moving from #45 to #25.</p><h2 id="strategic-tips-for-maximum-seo-impact" tabindex="-1"><strong>Strategic Tips for Maximum SEO Impact</strong> <a class="header-anchor" href="#strategic-tips-for-maximum-seo-impact" aria-label="Permalink to &quot;**Strategic Tips for Maximum SEO Impact**&quot;">​</a></h2><h3 id="understanding-the-top-3-5-advantage" tabindex="-1"><strong>Understanding the Top 3-5 Advantage</strong> <a class="header-anchor" href="#understanding-the-top-3-5-advantage" aria-label="Permalink to &quot;**Understanding the Top 3-5 Advantage**&quot;">​</a></h3><p>The biggest traffic boost comes from reaching positions #1-5 on each platform. This is where most listeners discover new podcasts:</p><ul><li><strong>Top 3 Rankings</strong>: Maximum visibility - most listeners choose from these results</li><li><strong>Positions #4-5</strong>: Strong visibility with significant discovery potential</li><li><strong>Rankings #6-10</strong>: On the edge of high visibility - small improvements here have outsized impact</li><li><strong>Rankings #11+</strong>: Lower discovery potential - use these to identify future opportunities rather than immediate optimization targets</li></ul><h3 id="prioritizing-your-efforts" tabindex="-1"><strong>Prioritizing Your Efforts</strong> <a class="header-anchor" href="#prioritizing-your-efforts" aria-label="Permalink to &quot;**Prioritizing Your Efforts**&quot;">​</a></h3><ul><li><strong>Focus on near-top rankings</strong>: Keywords where you rank #6-10 represent the highest-impact opportunities to reach top 5</li><li><strong>Maintain existing strengths</strong>: Keywords where you already rank top 5 should be reinforced, not neglected</li><li><strong>Cross-platform opportunities</strong>: Keywords performing well (#3-5) on one platform but not others show untapped potential</li><li><strong>Opportunistic approach</strong>: Use Show Visibility to see where you&#39;re ALREADY ranking, then optimize to push into top positions</li></ul><h3 id="building-your-strategy" tabindex="-1"><strong>Building Your Strategy</strong> <a class="header-anchor" href="#building-your-strategy" aria-label="Permalink to &quot;**Building Your Strategy**&quot;">​</a></h3><ul><li><strong>Use for Primary Keywords</strong>: Track keywords where you consistently rank in top 15 and add them to your Primary (max 3) or Secondary keywords list</li><li><strong>Monitor seasonal trends</strong>: Some keywords may perform better during specific times of year</li><li><strong>Track competitor movements</strong>: Notice when competitors drop in rankings for keywords where you also compete</li></ul><h3 id="measuring-success" tabindex="-1"><strong>Measuring Success</strong> <a class="header-anchor" href="#measuring-success" aria-label="Permalink to &quot;**Measuring Success**&quot;">​</a></h3><ul><li><strong>Small improvements matter</strong>: Moving up even 3-5 positions can significantly increase discovery</li><li><strong>Platform-specific wins</strong>: Success on one platform often translates to improvements on others over time</li><li><strong>Long-term perspective</strong>: Ranking improvements build momentum - consistent progress beats quick fixes</li></ul><h2 id="why-some-keywords-don-t-appear-in-show-visibility" tabindex="-1">Why Some Keywords Don&#39;t Appear in Show Visibility <a class="header-anchor" href="#why-some-keywords-don-t-appear-in-show-visibility" aria-label="Permalink to &quot;Why Some Keywords Don&#39;t Appear in Show Visibility&quot;">​</a></h2><p>If you&#39;re searching for a specific keyword and don&#39;t see it in Show Visibility, there are two possible reasons:</p><ol><li><p><strong>Your podcast doesn&#39;t rank in the top 50 for that keyword</strong> (most common): Show Visibility only shows keywords where your podcast currently ranks within the top 50 on at least one platform. If a keyword isn&#39;t listed, your podcast either hasn&#39;t achieved a ranking for it yet or ranks below position 50.</p></li><li><p><strong>The keyword isn&#39;t in PodSEO&#39;s database</strong> (rare): PodSEO tracks hundreds of thousands of keywords, but some niche terms might not be included yet.</p></li></ol><p><strong>Solution</strong>: Add any missing keyword to your <a href="/features/keyword-strategy.html">Keyword Strategy</a> page. This accomplishes two things:</p><ul><li>If the keyword wasn&#39;t in the database, it will be added and tracked</li><li>You can monitor it in Keyword Tracker to see when your podcast starts ranking for it</li><li>Once your podcast achieves a ranking for that keyword, it will appear in Show Visibility</li></ul><p><strong>Key Understanding</strong>: Show Visibility is a discovery tool that shows where you&#39;re ALREADY ranking - not a comprehensive list of all possible keywords. Think of it as &quot;here&#39;s what&#39;s working&quot; rather than &quot;here&#39;s everything you could rank for.&quot;</p><h2 id="plan-restrictions" tabindex="-1">Plan Restrictions <a class="header-anchor" href="#plan-restrictions" aria-label="Permalink to &quot;Plan Restrictions&quot;">​</a></h2><h3 id="free-plan" tabindex="-1">Free Plan <a class="header-anchor" href="#free-plan" aria-label="Permalink to &quot;Free Plan&quot;">​</a></h3><ul><li><strong>Visible Rows</strong>: First 10 rows only</li><li><strong>Additional Keywords</strong>: Blurred with a lock symbol for upgrade encouragement</li><li><strong>Upgrade Prompts</strong>: Clear upgrade messaging for full access</li><li><strong>Track Function</strong>: Available - can still add keywords to Keyword Strategy</li></ul><h3 id="paid-plans" tabindex="-1">Paid Plans <a class="header-anchor" href="#paid-plans" aria-label="Permalink to &quot;Paid Plans&quot;">​</a></h3><ul><li><strong>Full Visibility</strong>: Access to all keyword rankings your podcast appears for (top 50)</li><li><strong>Complete Data</strong>: All search volume and platform ranking data</li><li><strong>Higher Tracking Allowance</strong>: Every plan has a cap on total tracked keywords — Free 5, Podcaster 100, Producer 500, Agency 50,000. Adding a keyword beyond your plan&#39;s cap prompts an upgrade, so untrack keywords you no longer follow to free up slots.</li></ul><p><strong>Integration</strong>: Keywords tracked here automatically appear in your Keyword Strategy and can be analyzed in the Planner&#39;s metadata alignment for optimization recommendations.</p>',49)])])}const y=t(a,[["render",n]]);export{g as __pageData,y as default};
